"""Сборка автономных слайдов; --record обновляет реальные записи опытов."""
from pathlib import Path
import argparse,html,json,sys
ROOT=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT.parent/'presentation_assets'))
from upgrade_presentations import font_css,MATH_TOOLS

SLIDES=[]
def eq(tex):return '<div class="equation math-tex" data-tex="'+html.escape(tex,quote=True)+'"></div>'
def slide(title,body,tex=None,question=None,answer=None,minutes=2):
    if tex:body+=''.join(eq(t) for t in ([tex] if isinstance(tex,str) else tex))
    if question:body+='<aside class="discussion"><strong>Обсудим.</strong> '+question+'<details><summary>Показать разбор</summary><p>'+answer+'</p></details></aside>'
    SLIDES.append((title,body,minutes))
def slider(id,title,low,high,value,step=1):return f'<label>{title}<input id="{id}" type="range" min="{low}" max="{high}" step="{step}" value="{value}"><output></output></label>'
def stage(id,label):return f'<div class="stage"><canvas id="{id}" aria-label="{label}"></canvas></div>'
def controls(body):return '<div class="controls">'+body+'</div>'
def player():return '''<div class="lab" data-lab="robot"><div class="controls"><label>Опыт <select class="method"><option value="free">Без моторов</option><option value="gravity">Компенсация тяжести</option><option value="computed-torque">Computed torque</option><option value="mismatch">Computed torque: модель 80%</option><option value="impedance">Пространственная пружина + толчок</option></select></label><button class="play">▶ / Ⅱ</button><label>t <input class="scrub" type="range" min="0" max="7.98" step="any" value="0"><output class="clock">0 с</output></label></div><div class="split"><div class="stage"><canvas class="robot" aria-label="Записанная динамика 3R в MuJoCo"></canvas></div><div class="stage"><canvas class="plot" aria-label="Энергия и ошибка в выбранном опыте"></canvas></div></div><p class="status"></p></div>'''

slide('Пространственная динамика','<p class="eyebrow">Моделирование робототехнических систем · лекция 6</p><h1>Инерция.<br>Энергия. Движение.</h1><p class="lead">От уравнений твёрдого тела к динамике и управлению 3R.</p><p>Материалы ваших глав 6 и 7 · 90 минут</p>',minutes=1)
slide('Маршрут занятия','<div id="agenda"></div><p>Будем проверять формулы через энергию, независимую сборку модели и MuJoCo.</p>')
slide('Кинематика задаёт язык динамики','<p>Конфигурация H, твист T=(w;v), строка сил W=(τ F). Теперь добавляем инерцию и причины движения.</p>',[r'T_i^{k,0}=J_i^k(q)\dot q',r'\mathcal P=W_i^kT_i^{k,0}'],question='Что изменилось по сравнению с предыдущим MuJoCo-примером?',answer='Теперь задаём моменты и вызываем mj_step. Координаты q интегрируются, а не перезаписываются заданной траекторией.')
slide('Сохраняем вашу нотацию','<table><tr><th>Символ</th><th>Значение</th></tr><tr><td>Iᵏ˒ⁱ</td><td>Пространственная инерция тела i в Ψₖ</td></tr><tr><td>Pᵏ˒ⁱ</td><td>Импульс, строка</td></tr><tr><td>K, P(q)</td><td>Кинетическая и потенциальная энергии</td></tr><tr><td>N=∇P</td><td>Гравитация в левой части уравнения</td></tr><tr><td>τₐ</td><td>Строка моментов приводов</td></tr></table>')
slide('Инерция в системе центра масс','<p>Начало в CoM убирает перекрёстные блоки. Главные оси дополнительно делают J диагональной.</p>',r'I^{c_i,i}=\begin{bmatrix}J^{c_i,i}&0\\0&m_iI_3\end{bmatrix}',question='Любая система в центре масс делает J диагональной?',answer='Нет. Для диагонального J оси должны совпасть с главными осями инерции.')
slide('Энергия — квадратичная форма','<p>Пространственная инерция связывает скорость и импульс одного тела. Это ещё не суставная M(q).</p>',[r'K_i=\frac12(T_i^{c_i,0})^TI^{c_i,i}T_i^{c_i,0}',r'(P^{k,i})^T=I^{k,i}T_i^{k,0}'])
slide('Инерция зависит от системы выражения','<p>Пусть Tᵏ=A Tᶜ. Требуем, чтобы число K не изменилось.</p>',[r'(T^k)^TI^{k,i}T^k=(T^c)^TI^{c,i}T^c',r'\boxed{I^{k,i}=A^{-T}I^{c,i}A^{-1}}'],question='Почему не AᵀIA?',answer='Мы выразили новую скорость через старую. Для записи энергии через новую скорость подставляем старую через A⁻¹.')
slide('Перенос начала и теорема Штейнера','<p>При одинаковой ориентации и центре масс r относительно нового начала:</p>',r'I^{k,i}=\begin{bmatrix}J_c-m\widetilde r^{\,2}&m\widetilde r\\-m\widetilde r&mI_3\end{bmatrix}',question='Какой физический смысл у перекрёстных блоков?',answer='Вращение вокруг выбранного начала создаёт линейный импульс центра масс; перенос начала связывает угловую и линейную части.')
slide('Производная импульса','<p>В инерциальной системе сила равна производной импульса. В связанной системе меняется базис — появляются дополнительные члены.</p>',r'\dot P^{0,i}=W_i^0',question='Если J постоянно в системе тела, можно ли написать τ=Jẇ?',answer='В общем случае нельзя. Нужен член w×Jw, учитывающий вращение базиса.')
slide('Большой Ad и малый ad','<p>Ad меняет систему выражения. ad описывает взаимодействие мгновенных движений в алгебре.</p>',[r'\operatorname{ad}_T=\begin{bmatrix}\widetilde w&0\\\widetilde v&\widetilde w\end{bmatrix}',r'\operatorname{ad}_TT=0'])
slide('Уравнение одного тела','<p>Связанная система, постоянная I, T=Tᵢⁱ˒⁰. Строковое и столбцовое равенства эквивалентны.</p>',[r'\boxed{\dot P=P\operatorname{ad}_T+W}',r'\boxed{I\dot T-\operatorname{ad}_T^TIT=W^T}'],minutes=3)
slide('Раскрываем в центре масс','<p>Вращательная и линейная части в связанной системе:</p>',[r'J\dot w+w\times(Jw)=\tau^T',r'm\dot v+m(w\times v)=F^T'],question='Почему во втором уравнении есть w×v, хотя для CoM знакомо ma=F?',answer='v здесь выражено во вращающемся базисе. Инерциальная производная включает производную самого базиса.')
slide('Гироскопическая связь не потребляет мощность','<p>Нулевой энергетический вклад не означает нулевого влияния на траекторию.</p>',[r'T^T\operatorname{ad}_T^TIT=(\operatorname{ad}_TT)^TIT=0',r'\dot K=WT'],question='Можно ли убрать этот член из модели?',answer='Нет. В частности, исчезнет правильная динамика свободного вращения несимметричного тела.')
slide('Лаборатория гироскопического момента','<p>J=diag(0,02;0,04;0,055) кг·м². Меняйте угловую скорость; вычисления аналитические.</p>'+controls(slider('gyro-x','wₓ, рад/с',-8,8,.4,.1)+slider('gyro-y','wᵧ, рад/с',-8,8,5,.1)+slider('gyro-z','w<sub>z</sub>, рад/с',-8,8,.3,.1))+'<div id="gyro-values" class="equation"></div><p id="gyro-status"></p>',r'\tau_{\rm gyro}=w\times(Jw)',minutes=3)
slide('Промежуточная ось','<p>Jₓ&lt;Jᵧ&lt;J_z. Вращение около промежуточной оси неустойчиво к малым поперечным возмущениям.</p>',r'\ddot w_x=\Omega^2\frac{(J_y-J_z)(J_x-J_y)}{J_xJ_z}w_x',question='Откуда рост возмущения, если энергия не растёт?',answer='Энергия сохраняется, но перераспределяется между компонентами вращения. Неустойчивость относится к конкретному режиму.')
slide('Свободное вращение: анимация','<p>Запись численного решения уравнений Эйлера. RK4 для w, экспоненциальный midpoint для R; это отдельный Python-опыт.</p><div class="rigid controls"><label>Основная ось <select id="rigid-axis"><option value="middle">Промежуточная</option><option value="min">Минимальная</option><option value="max">Максимальная</option></select></label><button id="rigid-play">▶ / Ⅱ</button><label>t <input id="rigid-time" type="range" min="0" max="10" step="any" value="0"><output id="rigid-clock">0 с</output></label></div><div class="split">'+stage('rigid-body','Ориентация свободно вращающегося тела')+stage('rigid-plot','Компоненты угловой скорости')+'</div><p id="rigid-status"></p>',minutes=3)
slide('Что проверять в свободном вращении','<p>Сохранение энергии не заменяет проверку ориентации и инерциального углового импульса.</p>',[r'K=\frac12w^TJw=\mathrm{const}',r'L^0=R_i^0Jw=\mathrm{const}',r'R^TR=I'],question='Почему остатки K и L⁰ могут иметь разные порядки?',answer='В примере w интегрируется RK4, а R — методом второго порядка. Точность одного блока не определяет точность всей связки.')
slide('От одного тела к цепи','<p>Каждое звено имеет собственную инерцию и CoM. Все скорости нужно выразить в согласованных системах.</p>',r'K=\sum_iK_i,\qquad T_i^{0,0}=J_i(q)\dot q')
slide('Якобиан каждого звена','<p>Движения последующих суставов не меняют предыдущее звено: в Jᵢ соответствующие столбцы нулевые.</p>',[r'J_i=\begin{bmatrix}T_{s1}&\cdots&T_{si}&0&\cdots&0\end{bmatrix}',r'J_{b,i}=\operatorname{Ad}_{H_0^{c_i}}J_i'])
slide('Сборка суставной инерции','<p>Подставляем скорости звеньев в энергию и собираем коэффициенты при q̇.</p>',[r'K=\frac12\dot q^TM(q)\dot q',r'\boxed{M=\sum_iJ_{b,i}^TI^{c_i,i}J_{b,i}}'],question='Проверьте размеры множителей.',answer='Jb: 6×n; I: 6×6; результат каждого вклада: n×n.',minutes=3)
slide('Как читать M','<p>M симметрична и положительно определена. Внедиагональные элементы отражают связь обобщённых скоростей.</p><p>Даже при нулевых M₁₂ и M₁₃ связь может оставаться через зависимость M₁₁ от q₂,q₃.</p>',r'K=\frac12\sum_{i,j}M_{ij}(q)\dot q_i\dot q_j')
slide('Лаборатория суставной инерции','<p>Та же геометрия 3R, цилиндрические инерции. Масштаб меняет массы и инерции аналитической модели.</p>'+controls(slider('mass-q2','q₂, °',-90,90,30)+slider('mass-q3','q₃, °',-130,130,-45)+slider('mass-scale','Масштаб массы',.4,2,1,.1))+'<div class="lab-grid">'+stage('inertia','Эллипсоид постоянной кинетической энергии в пространстве суставных скоростей')+'<div id="mass-values" class="equation"></div></div><p id="mass-status"></p>',minutes=3)
slide('Потенциальная энергия','<p>Вертикаль +z, гравитация вниз. Компонент N находится в левой части уравнения.</p>',[r'P(q)=\sum_im_ig\,e_z^Tp_{c_i}^0(q)',r'N(q)=\frac{\partial P}{\partial q}'],question='Почему для удержания добавляем +N?',answer='Сама гравитация создаёт обобщённую силу −N. Мотор компенсирует её противоположным моментом.')
slide('Лагранж: первая производная','<p>Для K=½q̇ᵀMq̇ и симметричной M:</p>',[r'\frac{\partial K}{\partial\dot q_i}=\sum_jM_{ij}\dot q_j',r'\frac{d}{dt}\frac{\partial K}{\partial\dot q_i}=\sum_jM_{ij}\ddot q_j+\sum_{j,k}\frac{\partial M_{ij}}{\partial q_k}\dot q_k\dot q_j'])
slide('Лагранж: группируем члены','<p>После вычитания ∂K/∂qᵢ и добавления градиента потенциала:</p>',[r'\sum_jM_{ij}\ddot q_j+\sum_{j,k}\Gamma_{ijk}\dot q_j\dot q_k+\frac{\partial P}{\partial q_i}=Q_i',r'\Gamma_{ijk}=\frac12\left(\frac{\partial M_{ij}}{\partial q_k}+\frac{\partial M_{ik}}{\partial q_j}-\frac{\partial M_{jk}}{\partial q_i}\right)'])
slide('C — матрица, c — вектор','<p>Фиксируем стандартную конструкцию C через Кристоффеля. Нельзя называть C вектором и одновременно умножать её как матрицу.</p>',[r'C_{ij}=\sum_k\Gamma_{ijk}\dot q_k,\qquad c=C\dot q',r'M\ddot q+C\dot q+N=Q'])
slide('Внешний wrench и трение','<p>W₄⁰ — сила среды на робот, момент относительно начала Ψ₀. B — суставное вязкое сопротивление.</p>',r'\begin{aligned}M\ddot q+C\dot q+N+B\dot q&=\tau_a^T+J_s^T(W_4^0)^T.\end{aligned}')
slide('Энергетическая проверка робота','<p>Для выбранной C матрица Ṁ−2C кососимметрична.</p>',[r'\dot q^T(\dot M-2C)\dot q=0',r'\frac{d}{dt}(K+P)=\tau_a\dot q+W_4^0T_4^{0,0}-\dot q^TB\dot q'],question='Какие ошибки способен обнаружить этот баланс?',answer='Неверные знаки гравитации и сил, несовместимые системы wrench и twist, ошибки C или пространственной инерции.')
slide('Обратная динамика','<p>Состояние и желаемое ускорение → необходимый момент двигателя.</p>',r'\tau_a^T=M\ddot q+C\dot q+N+B\dot q-J_s^T(W_4^0)^T')
slide('Прямая динамика','<p>Моменты и текущее состояние → ускорение. Затем интегратор обновляет состояние.</p>',r'M\ddot q=\tau_a^T+J_s^T(W_4^0)^T-C\dot q-N-B\dot q',question='Зачем solve вместо inv(M)?',answer='Нужно решить линейную систему. Строить явную обратную матрицу для этого не требуется.')
slide('Рекурсивный Ньютон–Эйлер','<div class="pipeline">Вперёд: скорости и ускорения → назад: wrench звеньев и суставные моменты</div><p>Позволяет вычислять обратную динамику без символического раскрытия всей M. В учебном коде используем явную M для прозрачности и независимую проверку MuJoCo.</p>')
slide('Наша модель 3R','<p>Home-оси z,x,x; длины 0,4/0,35/0,25 м, массы 2/1,5/1 кг, радиус 0,025 м. Центры масс посередине звеньев.</p>',[r'J_{\parallel}=\frac12mr^2,\qquad J_{\perp}=\frac{m(3r^2+\ell^2)}{12}',r'B=0.06I,\quad |\tau_{a,i}|\le20\ {\rm N\,m}'],question='Геометрия capsule автоматически определяет инерции?',answer='Нет. В XML заданы явные inertial. Инерции соответствуют цилиндрам, а визуальная capsule служит рисунком.')
slide('Почему N₁=0','<p>Первый сустав вращает всю конструкцию вокруг вертикали. Высоты центров масс не меняются с q₁.</p>',[r'\frac{\partial P}{\partial q_1}=0\quad\Rightarrow\quad N_1=0',r'M(q)=\begin{bmatrix}\mu(q_2,q_3)&0&0\\0&a+2\beta\cos q_3&d+\beta\cos q_3\\0&d+\beta\cos q_3&d\end{bmatrix}'])
slide('Компенсация тяжести','<p>При точной модели и отсутствии внешних сил неподвижная начальная поза сохраняется.</p>',r'\tau_a^T=N(q)',question='Вернётся ли робот после толчка к исходной позе?',answer='Не обязательно. Позиционной пружины нет; вязкое трение лишь тормозит движение.')
slide('Computed torque из главы 7','<p>Ошибка e=q̄−q, виртуальное ускорение u. Модель вычисляется на текущем состоянии.</p>',[r'u=\ddot{\bar q}+K_v\dot e+K_pe',r'\tau_a^T=\hat M u+\hat C\dot q+\hat N+\hat B\dot q',r'\hat{\text{модель}}=\text{модель}\ \Rightarrow\ \ddot e+K_v\dot e+K_pe=0'])
slide('Неточная модель','<p>Сравним один физический XML и две модели регулятора: 100% и 80% массы и инерции. Шаг и коэффициенты не меняются.</p><p>Точные линейные уравнения ошибки справедливы только при точной компенсации, отсутствии внешних сил и насыщения.</p>',question='Если изменить массу одновременно в XML и контроллере, проверим ли ошибку модели?',answer='Нет. Это будет другой, но снова согласованный робот. Здесь меняем только номинальную модель регулятора.')
slide('Сила среды или сила робота?','<p>Для силы среды на робот F_ext эквивалентный момент положителен справа. Чтобы удержать позу, двигатель создаёт противоположный момент.</p>',[r'\tau_{\rm ext}=J_p^TF_{\rm ext}',r'\tau_a^T=N-J_p^TF_{\rm ext}'],question='Откуда плюс JᵀF_des в квазистатическом силовом управлении?',answer='F_des там означает силу робота на среду. Она противоположна силе среды на робот.')
slide('Лаборатория знака внешней силы','<p>Фиксированная поза q=(0,3;0,35;−0,55). Меняйте внешнюю силу по z, вычисляйте момент удержания.</p>'+controls(slider('force-z','F_ext,z, Н',-6,6,-3,.25))+'<div id="force-values" class="equation"></div><p id="force-status"></p>')
slide('Пространственная виртуальная пружина','<p>Выбираем явный энергетический частный случай, без общих coupling co-stiffness исходного PDF. Цель постоянна.</p>',r'U_s=\frac{k_p}{2}\|p-p_d\|^2+\frac{k_o}{2}\operatorname{tr}(I-R_d^TR)')
slide('Из потенциала — в силу и момент','<p>Ошибка ориентации e_R выражена в текущем базисе тела. Переводим момент в Ψ₀ через R.</p>',[r'e_R=\frac12\operatorname{vee}(R_d^TR-R^TR_d)',r'F_s=-k_p(p-p_d)-d_p\dot p',r'\tau_{\rm tip}^0=-k_oRe_R-d_ow'])
slide('Не перепутать точку момента','<p>Js работает с пространственным wrench относительно начала Ψ₀. Jp работает со скоростью точки tip.</p>',[r'W_s^0=\begin{bmatrix}(\tau_{\rm tip}^0+p\times F_s)^T&F_s^T\end{bmatrix}',r'J_s^T(W_s^0)^T=J_p^TF_s+J_\omega^T\tau_{\rm tip}^0'],question='Что будет, если забыть p×F?',answer='Вы приложите другой момент относительно начала Ψ₀. Закон управления перестанет соответствовать выбранной виртуальной пружине.')
slide('Энергия податливого управления','<p>Компенсируем N и добавляем виртуальную пружину с демпфированием.</p>',[r'\tau_a^T=N+J_p^TF_s+J_\omega^T\tau_{\rm tip}^0',r'\begin{aligned}\frac{d}{dt}(K+U_s)&=F_{\rm ext}^T\dot p-d_p\|\dot p\|^2\\&\quad-d_o\|w\|^2-\dot q^TB\dot q.\end{aligned}'],question='Это глобальная гарантия достижения любой позы?',answer='Нет. У 3R только три привода; у ориентационного потенциала есть дополнительные критические точки при 180°. В опыте цель достижима и взята из начальной позы.')
slide('MuJoCo: пять опытов на одном 3R','<p>Реальные записи динамического моделирования. Моторы задают момент, q интегрируется. Сцена вращается мышью.</p>'+player(),minutes=3)
slide('Читаем результаты','<div id="results-table"></div><p class="small">У computed torque цель движется; у остальных — начальная поза. Метрика не является рейтингом разных задач. Impedance испытывается толчком 3 Н между 3–5 с.</p>')
slide('Что именно проверено','<p>Три реализации M: аналитическая, энергетическая, MuJoCo. Проверены c+N, прямая и обратная динамика, Ṁ−2C, градиент P, перенос инерции, нулевая мощность gyro.</p><pre>python spatial_dynamics/verify.py</pre><p>В прогонах проверяются насыщение, удержание и ошибка слежения. Контакты отключены; внешняя сила задаётся через mj_applyFT.</p>')
slide('Практикум','<p>1. Сравните computed torque при масштабах модели 1 и 0,8.</p><p>2. В опыте свободного вращения сравните три главные оси.</p><p>3. Уменьшите шаг и сопоставьте остатки энергии и углового импульса.</p><p>4. Выведите знак момента удержания при внешней силе.</p>')
