def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--record',action='store_true');args=parser.parse_args()
    dest=ROOT/'presentation';recordpath=dest/'recordings.json'
    if args.record:
        from spatial_dynamics.simulate import run,metrics
        from spatial_dynamics.rigid_body import run as rigid
        records={'robot':{},'rigid':{}}
        for key,method,force,scale in [('free','free',False,1),('gravity','gravity',False,1),('computed-torque','computed-torque',False,1),('mismatch','computed-torque',False,.8),('impedance','impedance',True,1)]:
            rows=run(method,force=force,mass_scale=scale)
            records['robot'][key]={'rows':rows[::10].round(9).tolist(),'metrics':metrics(rows)}
        for i,axis in enumerate(('min','middle','max')):records['rigid'][axis]=rigid(axis=i)[::10].round(10).tolist()
        recordpath.write_text(json.dumps(records,separators=(',',':')))
    minutes=[s[2] for s in SLIDES]
    while sum(minutes)>90:
        index=max(range(1,len(minutes)-1),key=lambda i:(minutes[i],i));minutes[index]-=1
    while sum(minutes)<90:
        index=min(range(1,len(minutes)-1),key=lambda i:(minutes[i],i));minutes[index]+=1
    sections=''.join(f'<section class="slide" data-title="{html.escape(t,quote=True)}" data-minutes="{minutes[i]}" aria-label="{i+1}. {html.escape(t,quote=True)}"><h2>{html.escape(t)}</h2>{b}</section>' for i,(t,b,_) in enumerate(SLIDES))
    css=(dest/'deck.css').read_text();js=(dest/'deck.js').read_text();runtime=(ROOT.parent/'presentation_assets/katex-0.16.22/dist/katex.min.js').read_text()
    content=f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Лекция 6 · Пространственная динамика</title><style>{font_css()}\n{css}</style></head><body><header><strong>Пространственная динамика</strong><small>Лекция 6 · 90 минут</small><button id="menu">Обзор O</button><button id="fullscreen">Экран F</button></header><main>{sections}</main><footer><button id="previous" aria-label="Предыдущий слайд">←</button><span id="counter"></span><div class="progress"><i id="progress"></i></div><span id="time-label"></span><span class="hint">← → · O обзор · F экран · пробел пауза</span><button id="next" aria-label="Следующий слайд">→</button></footer><dialog id="overview"><button class="close">Закрыть</button><h2>Содержание</h2><div class="items"></div></dialog><dialog id="figure-modal"><button class="close">Закрыть</button><img alt=""></dialog><script id="recorded-data" type="application/json">{recordpath.read_text()}</script><script>{runtime}</script><script>{MATH_TOOLS}</script><script id="deck-code">{js}</script></body></html>'''
    (dest/'index.html').write_text(content)
    plan=['# План презентации: 90 минут','','| Время | Слайд |','|---|---|'];start=0
    for (title,_,_),duration in zip(SLIDES,minutes):plan.append(f'| {start}–{start+duration} | {title} |');start+=duration
    (dest/'TEACHING_PLAN.md').write_text('\n'.join(plan)+'\n');print(f'{len(SLIDES)} slides, {sum(minutes)} min, {len(content.encode())/1e6:.2f} MB')


if __name__=='__main__':main()
